const f = (col, row) => `=IFERROR(TRIM(LEFT(SUBSTITUTE(MID($A${row},FIND(CHAR(1),SUBSTITUTE($A${row},"#",CHAR(1),COLUMNS($B${row}:${col}${row})))+1,LEN($A${row}))," ",REPT(" ",100)),100)),"")`;
for (const r of [2,3]) for (const c of ['B','C']) wb.getRange(`${c}${r}`).setValue(f(c,r));
const out = [];
for (const a of ['B2','C2','B3','C3']) { const x = wb.getRange(a).getCell(); out.push([a, x.getValue(), x.getText(), x.getFormula ? x.getFormula() : '']); }
log(JSON.stringify(out));
log(JSON.stringify(wb.getRange('A1:C1').getValues()));
log(await wb.evaluate('=MID(A3,FIND("#vegetables",A3)+1,10)'));
wb.getRange('A1:C3')

